"""Command line interface: ``pennywise`` / ``python -m pennywise``."""

import argparse
import csv
import io
import json
import os
import sys

from .ledger import (
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_date,
    parse_line,
    sort_entries,
    split_lines,
)


class _Fail(Exception):
    """Abort with a message on stderr and an exit code."""

    def __init__(self, message, code):
        super().__init__(message)
        self.code = code


def _date_arg(text):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    p = argparse.ArgumentParser(prog="pennywise", description="Report on a plain-text ledger.")
    sub = p.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    s = sub.add_parser("balance", help="print the total")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("summary", help="print totals per category or month")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("list", help="print entries, oldest first")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--category")
    s.add_argument("--since", type=_date_arg, metavar="DATE")
    s.add_argument("--until", type=_date_arg, metavar="DATE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("add", help="append an entry")
    s.add_argument("file", metavar="FILE")
    s.add_argument("date", metavar="DATE")
    s.add_argument("category", metavar="CATEGORY")
    s.add_argument("amount", metavar="AMOUNT")
    s.add_argument("note", metavar="NOTE", nargs="?", default="")

    s = sub.add_parser("export", help="print entries as CSV")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--format", choices=["csv"], default="csv")
    return p


def _read_entries(path):
    try:
        if path == "-":
            # Decode bytes ourselves: ``sys.stdin.read()`` would use the locale
            # encoding and error handler, so stdin must match files (strict UTF-8).
            text = sys.stdin.buffer.read().decode("utf-8")
        else:
            with open(path, encoding="utf-8") as fh:
                text = fh.read()
    except (OSError, UnicodeDecodeError) as exc:
        raise _Fail("pennywise: %s: cannot read: %s" % (path, exc), 2)
    try:
        return parse(text)
    except ParseError as exc:
        raise _Fail("pennywise: %s: %s" % (path, exc), 1)


def _json(obj):
    return json.dumps(obj) + "\n"


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args):
    total = format_amount(balance(_read_entries(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _read_entries(args.file)
    totals = by_category(entries) if args.by == "category" else by_month(entries)
    names = sorted(totals)
    if args.json:
        return _json({n: format_amount(totals[n]) for n in names})
    return "".join("%s  %s\n" % (n, format_amount(totals[n])) for n in names)


def _selected(args):
    entries = _read_entries(args.file)
    return sort_entries(filter_entries(entries, args.category, args.since, args.until))


def _cmd_list(args):
    entries = _selected(args)
    if args.json:
        return _json([_entry_dict(e) for e in entries])
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = sort_entries(_read_entries(args.file))
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(["date", "category", "amount", "note"])
    for e in entries:
        w.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buf.getvalue()


def _is_one_field(value):
    """True when value is non-empty and holds no ASCII space or tab."""
    return bool(value) and not any(c in " \t" for c in value)


def _cmd_add(args):
    path = args.file
    if path == "-":
        raise _Fail("pennywise: add: FILE cannot be '-' (stdin)", 2)
    try:
        with open(path, "rb") as fh:
            existing = fh.read()
    except FileNotFoundError:
        existing = b""
    except OSError as exc:
        raise _Fail("pennywise: %s: cannot read: %s" % (path, exc), 2)

    # A leading UTF-8 BOM is not content: keep it in the file, ignore it here.
    body = existing[3:] if existing.startswith(b"\xef\xbb\xbf") else existing
    number = len(split_lines(body.decode("utf-8", errors="replace"))) + 1
    try:
        if not args.category or not _is_one_field(args.category):
            raise ParseError("category must be one non-empty word", number)
        for value in (args.date, args.amount):
            if not _is_one_field(value):
                raise ParseError("invalid field %r" % value, number)
        line = " ".join([args.date, args.category, args.amount] + ([args.note] if args.note else []))
        if len(split_lines(line)) != 1:
            raise ParseError("note must be a single line", number)
        entry = parse_line(line, number)
    except ParseError as exc:
        raise _Fail("pennywise: %s: %s" % (path, exc), 1)

    out = format_entry(entry)
    prefix = b"\n" if body and not body.endswith(b"\n") else b""
    try:
        with open(path, "ab") as fh:
            fh.write(prefix + (out + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Fail("pennywise: %s: cannot write: %s" % (path, exc), 2)
    return out + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = _COMMANDS[args.command](args)
    except _Fail as exc:
        print(str(exc), file=sys.stderr)
        return exc.code
    try:
        # Characters stdout cannot encode (``PYTHONIOENCODING=ascii``, a POSIX
        # locale) print as backslash escapes instead of crashing -- by now
        # ``add`` has already changed the file, so it must still exit 0.
        try:
            sys.stdout.reconfigure(errors="backslashreplace")
        except (AttributeError, ValueError, OSError):
            pass
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        # Reader went away early (e.g. ``| head -1``). Exit quietly like other
        # Unix tools; point stdout at devnull so the flush at interpreter exit
        # cannot raise again.
        try:
            fileno = sys.stdout.fileno()
            devnull = os.open(os.devnull, os.O_WRONLY)
            try:
                os.dup2(devnull, fileno)
            finally:
                os.close(devnull)
        except (OSError, ValueError, AttributeError):
            pass
    return 0
